const CODE_SNAP_KEYWORDS ={javascript: ["const","let","var","function","return","if","else","for","while","class","extends","import","export","default","async","await","new","this","typeof","null","undefined","true","false","try","catch","throw"], python: ["def","return","if","elif","else","for","while","class","import","from","as","with","try","except","finally","lambda","None","True","False","self","yield","async","await"], generic: [],};const CODE_SNAP_THEMES ={phosphor:{bg: ["#0a0a0a", "#10160f"], window: "#0d1a12", text: "#e8e8e8", keyword: "#00FF66", string: "#3C965F", comment: "#555555", number: "#ff9500"}, dusk:{bg: ["#1a1a2e", "#16213e"], window: "#0f0f1e", text: "#e0e0e0", keyword: "#e94560", string: "#0f9b8e", comment: "#6c6c8a", number: "#ffd369"}, paper:{bg: ["#f4f1ea", "#e8e2d5"], window: "#ffffff", text: "#2b2b2b", keyword: "#a4133c", string: "#606c38", comment: "#a3a3a3", number: "#bc6c25"},};function codeSnapTokenizeLine(line, kwSet){const tokens = [];const re = /(\/\/[^\n]*|#[^\n]*|"([^"\\]|\\.)*"|'([^'\\]|\\.)*'|`([^`\\]|\\.)*`|\b\d+(\.\d+)?\b|\b[a-zA-Z_][a-zA-Z0-9_]*\b|\s+|.)/g;let m;while ((m = re.exec(line)) !== null){const text = m[0];let type = "plain";if (/^(\/\/|#)/.test(text)) type = "comment";else if (/^['"`]/.test(text)) type = "string";else if (/^\d/.test(text)) type = "number";else if (kwSet.has(text)) type = "keyword";tokens.push({text, type});}return tokens;}function codeSnapTokenizeCode(code, lang){const kwSet = new Set(CODE_SNAP_KEYWORDS[lang] || []);return code.split("\n").map((line) => codeSnapTokenizeLine(line, kwSet));}function renderCodeSnap(){const code = document.getElementById("snap-input").value;const lang = document.getElementById("snap-lang").value;const themeKey = document.getElementById("snap-theme").value;const showChrome = document.getElementById("snap-chrome").checked;const canvas = document.getElementById("snap-canvas");const ctx = canvas.getContext("2d");if (!code){canvas.width = 0;canvas.height = 0;return;}const theme = CODE_SNAP_THEMES[themeKey];const lines = codeSnapTokenizeCode(code, lang);const fontSize = 16;const lineHeight = fontSize * 1.5;const padX = 32;const padY = 28;const chromeHeight = showChrome ? 36 : 0;const font = `${fontSize}px "JetBrains Mono", "Fira Code", Consolas, monospace`; const measureCanvas = document.createElement("canvas");const mctx = measureCanvas.getContext("2d");mctx.font = font;let maxWidth = 200;lines.forEach((tokens) =>{const w = tokens.reduce((sum, t) => sum + mctx.measureText(t.text).width, 0);if (w > maxWidth) maxWidth = w;});const outerPad = 40;const windowWidth = maxWidth + padX * 2;const windowHeight = lines.length * lineHeight + padY * 2 + chromeHeight;canvas.width = windowWidth + outerPad * 2;canvas.height = windowHeight + outerPad * 2; const grad = ctx.createLinearGradient(0, 0, canvas.width, canvas.height);grad.addColorStop(0, theme.bg[0]);grad.addColorStop(1, theme.bg[1]);ctx.fillStyle = grad;ctx.fillRect(0, 0, canvas.width, canvas.height); const wx = outerPad, wy = outerPad, wr = 12;ctx.save();ctx.shadowColor = "rgba(0,0,0,0.4)";ctx.shadowBlur = 24;ctx.shadowOffsetY = 8;ctx.fillStyle = theme.window;ctx.beginPath();ctx.moveTo(wx + wr, wy);ctx.arcTo(wx + windowWidth, wy, wx + windowWidth, wy + windowHeight, wr);ctx.arcTo(wx + windowWidth, wy + windowHeight, wx, wy + windowHeight, wr);ctx.arcTo(wx, wy + windowHeight, wx, wy, wr);ctx.arcTo(wx, wy, wx + windowWidth, wy, wr);ctx.closePath();ctx.fill();ctx.restore(); if (showChrome){const dotColors = ["#ff5f56", "#ffbd2e", "#27c93f"];dotColors.forEach((c, i) =>{ctx.beginPath();ctx.arc(wx + 24 + i * 22, wy + chromeHeight / 2, 6, 0, Math.PI * 2);ctx.fillStyle = c;ctx.fill();});} ctx.font = font;ctx.textBaseline = "top";lines.forEach((tokens, lineIdx) =>{let x = wx + padX;const y = wy + chromeHeight + padY + lineIdx * lineHeight;tokens.forEach((t) =>{ctx.fillStyle = theme[t.type] || theme.text;ctx.fillText(t.text, x, y);x += ctx.measureText(t.text).width;});});}function downloadCodeSnap(){const canvas = document.getElementById("snap-canvas");if (!canvas.width) return;const link = document.createElement("a");link.download = "gamayun-code-snap.png";link.href = canvas.toDataURL("image/png");link.click();GAMA.log("Downloaded code snap PNG");GAMA.say("success");}document.addEventListener("DOMContentLoaded", () =>{const input = document.getElementById("snap-input");if (input){["snap-input", "snap-lang", "snap-theme", "snap-chrome"].forEach((id) =>{document.getElementById(id).addEventListener("input", renderCodeSnap);});}});